"""Format a dict back to sorted ``key=value`` lines."""


def fmt(data: dict) -> str:
    """Return ``key=value`` lines sorted by key, newline-terminated."""
    return "".join(f"{k}={data[k]}\n" for k in sorted(data))
EOF
