import pytest

from kv.fmt import fmt
from kv.parse import parse


def test_parse_basic():
    assert parse("a=1\nb=2\n") == {"a": "1", "b": "2"}


def test_parse_skips_blank_and_comments():
    assert parse("# c\n\na=1\n") == {"a": "1"}


def test_parse_splits_on_first_equals():
    assert parse("a=b=c") == {"a": "b=c"}


def test_parse_invalid_line():
    with pytest.raises(ValueError):
        parse("nokey")


def test_fmt_sorted():
    assert fmt({"b": "2", "a": "1"}) == "a=1\nb=2\n"


def test_fmt_empty():
    assert fmt({}) == ""


def test_roundtrip():
    d = {"x": "1", "a": "b=c"}
    assert parse(fmt(d)) == d
EOF
